import pandas as pd
import numpy as np
import json
import os
from itertools import combinations

PARAMS = {
    "columna_id": "id",
    "columna_grupo": "region",
    "deduplicar": True,
    "aparicion_conservada": "first",
    "aceptar_coma_decimal": True,
    "max_fraccion_ausentes": 0.20,
    "metodo_correlacion": "pearson",
    "correlacion_absoluta": True,
    "umbral_desviaciones": 4.5,
    "factor_mad": 1.4826,
    "omitir_mad_cero": True,
    "anomalias_por_grupo": True,
}

if os.path.exists('params.json'):
    with open('params.json', 'r', encoding='utf-8') as f:
        PARAMS.update(json.load(f))

COL_ID = PARAMS["columna_id"]
COL_GRUPO = PARAMS["columna_grupo"]

# 1. Cargar CSV
df = pd.read_csv('datos.csv', dtype=str, keep_default_na=False)

# Strip espacios
for col in df.columns:
    df[col] = df[col].str.strip()

# 2. Deduplicar
if PARAMS["deduplicar"]:
    df = df.drop_duplicates(subset=COL_ID, keep=PARAMS["aparicion_conservada"])
df = df.reset_index(drop=True)

# Definir columnas numéricas
num_cols = [c for c in df.columns if c not in [COL_ID, COL_GRUPO]]

# 3. Convertir numéricas
for col in num_cols:
    def convert_to_float(x):
        if x == '':
            return np.nan
        if PARAMS["aceptar_coma_decimal"]:
            x = x.replace(',', '.')
        try:
            return float(x)
        except:
            return np.nan

    df[col] = df[col].apply(convert_to_float)

# 4. Calcular elegibilidad
elegibles = []
for col in num_cols:
    nan_pct = df[col].isna().mean()
    if nan_pct <= PARAMS["max_fraccion_ausentes"]:
        elegibles.append(col)

# 5. Calcular correlaciones
max_corr = -1
best_pair = None

for col_a, col_b in combinations(elegibles, 2):
    mask = df[col_a].notna() & df[col_b].notna()
    if mask.sum() < 2:
        continue

    corr = df.loc[mask, col_a].corr(df.loc[mask, col_b], method=PARAMS["metodo_correlacion"])

    if pd.isna(corr):
        continue

    abs_corr = abs(corr) if PARAMS["correlacion_absoluta"] else corr

    if abs_corr > max_corr:
        max_corr = abs_corr
        best_pair = sorted([col_a, col_b])

# 6. Detectar anomalías
anomalias_set = set()

if PARAMS["anomalias_por_grupo"]:
    grupos_indices = [df[df[COL_GRUPO] == region].index for region in df[COL_GRUPO].unique()]
else:
    grupos_indices = [df.index]

for region_indices in grupos_indices:
    for col in num_cols:
        values = df.loc[region_indices, col].dropna()

        if len(values) == 0:
            continue

        mediana = values.median()
        mad = (values - mediana).abs().median()

        if mad == 0 and PARAMS["omitir_mad_cero"]:
            continue

        threshold = PARAMS["umbral_desviaciones"] * PARAMS["factor_mad"] * mad

        for idx in region_indices:
            val = df.loc[idx, col]
            if pd.isna(val):
                continue

            if abs(val - mediana) > threshold:
                anomalias_set.add(df.loc[idx, COL_ID])

# 7. Resultado
resultado = {
    "par": best_pair,
    "anomalias": sorted(list(anomalias_set))
}

print(json.dumps(resultado, ensure_ascii=False))
